import{_ as s,l as o,o as e,c as n,v as r,p as l,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"流算法 Misra–Gries","description":"","frontmatter":{"title":"流算法 Misra–Gries","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/misra-gries.md","filePath":"cs/misra-gries.md","lastUpdated":1789023840000}'),c={name:"cs/misra-gries.md"};function m(_,a,u,k,f,M){const t=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="流算法-misra–gries" tabindex="-1">流算法 Misra–Gries <a class="header-anchor" href="#流算法-misra–gries" aria-label="Permalink to &quot;流算法 Misra–Gries&quot;">​</a></h1><div class="epigraph"><p>一遍扫描，$k-1$ 个计数器找出频率 $\\gt n/k$ 的候选项；真频繁项不会漏，假阳性再扫或抽样验证。</p><footer>—— 据 Misra and Gries, Finding Repeated Elements, 1982；Cormode and Hadjieleftheriou 流频繁项综述整理</footer></div><p>上一课<a href="/cs/simulated-annealing">模拟退火</a>收束元启发。图流课已说空间小。本课项流：宇宙很大，找频繁项。缺口是 Misra–Gries（与 Boyer–Moore 多数投票推广）。不重写半流图森林。后课外存 I/O。接<a href="/cs/graph-streaming">图流</a>对象是边，本课是元素序列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长 \\(n\\) 的流，找出现 \\(\\gt n/k\\) 的项（至多 \\(k-1\\) 个真）。MG：维护 \\(\\le k-1\\) 个 (item,count)。新项已在则加；表满且不在则全体减 1，计数 0 的丢掉。真频繁项始终在表中（或结束时计数被低估但仍在）。Count-Min、SpaceSaving 点名。</p><p>缺口是固定 \\(k\\) 空间，不是排序。</p><h3 id="不是精确直方图" tabindex="-1">不是精确直方图 <a class="header-anchor" href="#不是精确直方图" aria-label="Permalink to &quot;不是精确直方图&quot;">​</a></h3><p>输出是候选。假阳性有。要精确再第二遍。不要声称一遍精确所有频率。</p><p><span class="marginnote">Misra–Gries 1982。Majority Boyer–Moore 是 \\(k=2\\)。后课外存是另一内存层次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(k\\) 给定。一遍 MG。需要频率下界：\\(\\hat f(e)\\ge f(e)-n/k\\)。第二遍过滤。</p>',11)),(e(),l(h,null,{default:i(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E5%85%83%E7%B4%A0%E6%B5%81%22%5D%20--%3E%20MG%5B%22k-1%20%E4%B8%AA%E8%AE%A1%E6%95%B0%E5%99%A8%22%5D%0A%20%20MG%20--%3E%20CAND%5B%22%3E%20n%2Fk%20%E5%80%99%E9%80%89%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>并行多 \\(k\\) 或分层。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每次「全体减一」对应扔掉 \\(k\\) 个不同项各一次，最多扔掉 \\(n/k\\) 轮对某真频繁的伤害。与指纹：MG 确定；Count-Min 哈希 MC。与 Karger：都是小空间摘要，对象不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 sketch 下界。不写分布式。后课默认：频繁项用 MG/SpaceSaving。下一课外存与 I/O 模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(k-1\\) 计数器一遍流。</li><li>真 \\(\\gt n/k\\) 不漏；频率低估。</li><li>精确需第二遍。</li><li>出处：Misra and Gries, 1982。</li></ul>',7))])}const A=s(c,[["render",m]]);export{E as __pageData,A as default};
